import React from 'react';
import { ModalProvider, useModal } from '@my-app/modal';

function ModalTest() {
  const { confirm, alert } = useModal();

  const handleConfirmTest = async () => {
    const result = await confirm('이 작업을 계속하시겠습니까?');
    console.log('Confirm result:', result);
  };

  const handleAlertTest = async () => {
    await alert('알림 메시지입니다!');
    console.log('Alert closed');
  };

  const handleCustomModalTest = async () => {
    const result = await confirm('커스텀 옵션 모달입니다.', {
      enableOutsideClick: false,
      enableKeyboardShortcuts: false,
      showCancelButton: true
    });
    console.log('Custom modal result:', result);
  };

  return (
    <div>
      <h2>Modal Package Tests</h2>
      <div style={{ display: 'flex', gap: '10px', flexDirection: 'column', alignItems: 'center' }}>
        <button onClick={handleConfirmTest}>Confirm Modal Test</button>
        <button onClick={handleAlertTest}>Alert Modal Test</button>
        <button onClick={handleCustomModalTest}>Custom Options Modal Test</button>
      </div>
    </div>
  );
}

export default ModalTest;
